import java.util.Scanner;
public class KadaneAlgorithm { public static int maxSubarraySum(int[]a){if(a.length==0)throw new IllegalArgumentException("Empty array");int current=a[0],best=a[0];for(int i=1;i<a.length;i++){current=Math.max(a[i],current+a[i]);best=Math.max(best,current);}return best;}public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Enter array size: ");int n=sc.nextInt();if(n<=0){System.out.println("Size must be positive.");sc.close();return;}int[]a=new int[n];System.out.println("Enter elements:");for(int i=0;i<n;i++)a[i]=sc.nextInt();System.out.println("Maximum subarray sum: "+maxSubarraySum(a));sc.close();} }